export type Item = {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
};

export type Step = {
  op: string;
  items?: Item[];
};

export type Scenario = {
  customer: { yearsWithMHPCO: number };
  steps: Step[];
};

export type ScenarioResults = {
  results: unknown[];
};

const PROCESSING_FEE = 5;

const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
  sword: 100,
  amulet: 60,
};

const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;

const addPercent = (amount: number, percent: number): number =>
  amount + (amount * percent) / 100;

const basePremiumOf = (items: Item[]): number =>
  items.reduce((sum, item) => sum + BASE_PREMIUM_BY_TYPE[item.type], 0);

const calculatePremium = (items: Item[]): number =>
  addPercent(basePremiumOf(items), FIRST_INSURANCE_SURCHARGE_PERCENT) +
  PROCESSING_FEE;

export const runScenario = (scenario: Scenario): ScenarioResults => ({
  results: scenario.steps.map((step) => ({
    premium: calculatePremium(step.items ?? []),
  })),
});

