import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Edge case: empty policy ---
  it("empty item list → premium 5 G (only the processing fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [] }],
    });

    expect(result).toEqual({ results: [{ premium: 5 }] });
  });

  // --- Base premiums per main item type (plus 5 G fee, first insurance 10 %) ---
  it("single plain sword, new customer → base premium 100 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "sword", material: "steel", enchantment: 3, cursed: false }],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 115 }] });
  });
  it("single plain amulet, new customer → base premium 60 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "amulet", material: "silver", enchantment: 2, cursed: false }],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 71 }] });
  });
  it("single plain staff, new customer → base premium 80 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "staff", material: "oak", enchantment: 2, cursed: false }],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 93 }] });
  });
  it("single plain potion, new customer → base premium 40 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "potion", material: "glass", enchantment: 1, cursed: false }],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 49 }] });
  });

  // --- Components ---
  it("single rune → base premium 25 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "rune" }] }],
    });

    expect(result).toEqual({ results: [{ premium: 33 }] });
  });
  it.todo("single moonstone → base premium 25 G");
  it.todo("2 runes → 50 G base premium");
  it.todo("3 runes → 60 G base premium (block of 3 alike applies)");
  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
  it.todo("7 runes → 175 G base premium (no block for 7)");

  // --- "Alike" components ---
  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");

  // --- Individual premium modifiers ---
  it.todo("cursed sword adds a 50 % risk surcharge on the item's base premium");
  it.todo("sword with enchantment 5 adds a 30 % high-enchantment surcharge");
  it.todo("sword with enchantment 4 → no high-enchantment surcharge");
  it.todo("cursed sword with enchantment 5 → both surcharges apply");
  it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
  it.todo("customer with 1 year with MHPCO → no loyalty discount");
  it.todo("first quote in a scenario carries the 10 % initial assessment surcharge");
  it.todo("second quote in a scenario receives the 15 % follow-up contract discount");
  it.todo("first insurance surcharge applies to every quote's items regardless of customer history");

  // --- Modifier scope on multi-item policies ---
  it.todo(
    "cursed sword + plain amulet → policy base 160 G, curse adds 50 G (item-scoped) → 210 G before further modifiers and fee",
  );
  it.todo("policy-wide modifiers (loyalty, first insurance, follow-up) apply to the policy base premium");
  it.todo("the 5 G processing fee is added at the very end");

  // --- Rounding in the MHPCO's favor ---
  it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
  it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");
  it.todo("intermediate amounts are kept as fractions; only the final amount is rounded");

  // --- Standard claim reimbursement ---
  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
  it.todo("damage to a rune (value 250 G), damage 200 G → payout 100 G (no special clause)");

  // --- Enchantment threshold vs. dragon material ---
  it.todo("dragon-material sword, enchantment 8, damage 1000 G → payout 400 G");
  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins, then deductible)");
  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");

  // --- Deductible per damage event ---
  it.todo("dragon attack damages sword (500 G) and amulet (300 G) → payout 600 G (deductible once per damaged item)");

  // --- Insurance sum and cap ---
  it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
  it.todo("a cursed sword → cap 2000 G (premium modifiers do not raise the cap)");
  it.todo("a policy covering a sword and 3 runes → insurance sum 1750 G (block discount affects premium only)");
  it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");

  // --- Cap exhaustion across successive claims ---
  it.todo("sword (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
  it.todo("sword (cap 2000 G), second claim of 1500 G → payout 600 G, remainingCap 0 G");

  // --- Multiple items of the same type ---
  it.todo("two sword damage entries against a policy with two swords → each entry gets its own deductible");
  it.todo("more damage entries of a type than the policy covers → error (claim rejected)");

  // --- Error cases ---
  it.todo("quote with an unknown item type (e.g. broomstick) → error");
  it.todo("claim referencing an item not part of the policy (amulet damaged, only sword insured) → error");
  it.todo("claim referencing a damage entry with an unknown item type → error");
  it.todo("claim with a damage entry of amount -200 → error");

  // --- Integration examples ---
  it.todo("newcomer with a cursed sword (0 years, no previous contract) → premium 165 G");
  it.todo("long-standing customer's second contract with a cursed sword (3 years, enchantment 7) → premium 160 G");

  // --- CLI-level scenario ---
  it.todo("schema example scenario → results array with a quote premium and a claim payout/remainingCap");
});

