export type Item = {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
};

export type Step = {
  op: string;
  items?: Item[];
};

export type Scenario = {
  customer: { yearsWithMHPCO: number };
  steps: Step[];
};

export type QuoteResult = {
  premium: number;
};

export type ScenarioResults = {
  results: QuoteResult[];
};

const PROCESSING_FEE = 5;

const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;

const addPercent = (amount: number, percent: number): number =>
  amount + (amount * percent) / 100;

const itemBasePremium = (item: Item): number =>
  BASE_PREMIUM_BY_TYPE[item.type];

const BLOCK_SIZE = 3;

const BLOCK_PREMIUM = 60;

const areAlike = ([first, ...rest]: Item[]): boolean =>
  rest.every((item) => item.type === first.type);

const formsABlock = (items: Item[]): boolean =>
  items.length === BLOCK_SIZE && areAlike(items);

const sumOfItemBasePremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + itemBasePremium(item), 0);

const policyBasePremium = (items: Item[]): number =>
  formsABlock(items) ? BLOCK_PREMIUM : sumOfItemBasePremiums(items);

const roundPremiumInMHPCOsFavor = (amount: number): number =>
  Math.ceil(amount);

const quotePremium = (items: Item[]): number =>
  roundPremiumInMHPCOsFavor(
    addPercent(policyBasePremium(items), FIRST_INSURANCE_SURCHARGE_PERCENT) +
      PROCESSING_FEE,
  );

export const runScenario = (scenario: Scenario): ScenarioResults => ({
  results: scenario.steps.map((step) => ({
    premium: quotePremium(step.items ?? []),
  })),
});

