// The inputs a single quote is computed from. Today only `items` is consumed;
// `customer` is threaded through so policy-wide modifiers that depend on
// customer history (loyalty, follow-up contract) have a seat at the table.
type QuoteRequest = {
  customer: Customer;
  items: Item[];
};

// Every test so far quotes a new customer's first contract, so this is the only
// policy-wide modifier the tests demand. Loyalty and follow-up land here later;
// `quotePremium` already holds the customer and can pass it in at that point.
const applyPolicyModifiers = (basePremium: number): number =>
  addPercent(basePremium, FIRST_INSURANCE_SURCHARGE_PERCENT);

const CURSE_SURCHARGE_PERCENT = 50;

const HIGH_ENCHANTMENT_LEVEL = 5;

const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;

const isHighlyEnchanted = (item: Item): boolean =>
  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;

const isCursed = (item: Item): boolean => item.cursed === true;

type ItemSurchargeRule = {
  applies: (item: Item) => boolean;
  percent: number;
};

const ITEM_SURCHARGE_RULES: ItemSurchargeRule[] = [
  { applies: isCursed, percent: CURSE_SURCHARGE_PERCENT },
  { applies: isHighlyEnchanted, percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT },
];

// Item-scoped surcharges are charged on the item's own base premium, so they
// must NOT go through applyPolicyModifiers.
const itemSurcharges = (item: Item): number =>
  sumOf(
    ITEM_SURCHARGE_RULES.filter((rule) => rule.applies(item)).map((rule) =>
      percentOf(itemBasePremium(item), rule.percent),
    ),
  );

