export type Item = {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
};

export type Step = {
  op: string;
  items?: Item[];
};

export type Customer = {
  yearsWithMHPCO: number;
};

export type Scenario = {
  customer: Customer;
  steps: Step[];
};

export type QuoteResult = {
  premium: number;
};

export type ScenarioResults = {
  results: QuoteResult[];
};

const PROCESSING_FEE = 5;

const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;

const percentOf = (amount: number, percent: number): number =>
  (amount * percent) / 100;

const addPercent = (amount: number, percent: number): number =>
  amount + percentOf(amount, percent);

const itemBasePremium = (item: Item): number =>
  BASE_PREMIUM_BY_TYPE[item.type];

const BLOCK_SIZE = 3;

const BLOCK_PREMIUM = 60;

const sumOf = (amounts: number[]): number =>
  amounts.reduce((sum, amount) => sum + amount, 0);

const formsABlock = (items: Item[]): boolean => items.length === BLOCK_SIZE;

const sumOfItemBasePremiums = (items: Item[]): number =>
  sumOf(items.map(itemBasePremium));

const groupByType = (items: Item[]): Item[][] => {
  const types = new Set(items.map((item) => item.type));

  return [...types].map((type) => items.filter((item) => item.type === type));
};

const alikeGroupBasePremium = (items: Item[]): number =>
  formsABlock(items) ? BLOCK_PREMIUM : sumOfItemBasePremiums(items);

const policyBasePremium = (items: Item[]): number =>
  sumOf(groupByType(items).map(alikeGroupBasePremium));

const roundPremiumInMHPCOsFavor = (amount: number): number =>
  Math.ceil(amount);

// The inputs a single quote is computed from. Today only `items` is consumed;
// `customer` is threaded through so policy-wide modifiers that depend on
// customer history (loyalty, follow-up contract) have a seat at the table.
type QuoteRequest = {
  customer: Customer;
  items: Item[];
};

// Every test so far quotes a new customer's first contract, so this is the only
// policy-wide modifier the tests demand. Loyalty and follow-up land here later;
// `quotePremium` already holds the customer and can pass it in at that point.
const applyPolicyModifiers = (basePremium: number): number =>
  addPercent(basePremium, FIRST_INSURANCE_SURCHARGE_PERCENT);

const CURSE_SURCHARGE_PERCENT = 50;

const HIGH_ENCHANTMENT_LEVEL = 5;

const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;

const isHighlyEnchanted = (item: Item): boolean =>
  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;

const isCursed = (item: Item): boolean => item.cursed === true;

type ItemSurchargeRule = {
  applies: (item: Item) => boolean;
  percent: number;
};

const ITEM_SURCHARGE_RULES: ItemSurchargeRule[] = [
  { applies: isCursed, percent: CURSE_SURCHARGE_PERCENT },
  { applies: isHighlyEnchanted, percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT },
];

// Item-scoped surcharges are charged on the item's own base premium, so they
// must NOT go through applyPolicyModifiers.
const itemSurcharges = (item: Item): number =>
  sumOf(
    ITEM_SURCHARGE_RULES.filter((rule) => rule.applies(item)).map((rule) =>
      percentOf(itemBasePremium(item), rule.percent),
    ),
  );

const policyItemSurcharges = (items: Item[]): number =>
  sumOf(items.map(itemSurcharges));

const quotePremium = (request: QuoteRequest): number =>
  roundPremiumInMHPCOsFavor(
    applyPolicyModifiers(policyBasePremium(request.items)) +
      policyItemSurcharges(request.items) +
      PROCESSING_FEE,
  );

export const runScenario = (scenario: Scenario): ScenarioResults => ({
  results: scenario.steps.map((step) => ({
    premium: quotePremium({
      customer: scenario.customer,
      items: step.items ?? [],
    }),
  })),
});

