const HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;

const HALF_REIMBURSEMENT_PERCENT = 50;

const isHalfReimbursed = (item: Item): boolean =>
  (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL;

const damagedItem = (insuredItems: Item[], damage: Damage): Item | undefined =>
  insuredItems.find((item) => item.type === damage.itemType);

// What a damage entry reimburses before the deductible: the full damage amount,
// unless a special clause on the damaged item says otherwise.
const reimbursableAmount = (insuredItems: Item[], damage: Damage): number => {
  const item = damagedItem(insuredItems, damage);

  return item && isHalfReimbursed(item)
    ? percentOf(damage.amount, HALF_REIMBURSEMENT_PERCENT)
    : damage.amount;
};

