const runQuoteStep: StepRunner = (customer, state, step, stepIndex) => {
  const items = step.items ?? [];

  const premium = quotePremium({
    customer,
    items,
    precedingQuoteCount: state.precedingQuoteCount,
  });

  return {
    ...appendResult(state, { premium }),
    precedingQuoteCount: state.precedingQuoteCount + 1,
    policiesByStep: new Map(state.policiesByStep).set(stepIndex, items),
  };
};

// A claim names its policy by the index of the quote step that created it. An
// unnamed or unknown policy currently yields no insured items, and so a cap of
// 0 — the pending error-handling tests will replace this with a rejection.
const insuredItemsFor = (state: ScenarioState, step: Step): Item[] =>
  step.policy === undefined ? [] : (state.policiesByStep.get(step.policy) ?? []);

const runClaimStep: StepRunner = (_customer, state, step) => {
  const damages = step.incident?.damages ?? [];
  const insuredItems = insuredItemsFor(state, step);

  const payout = sumOf(
    damages.map((damage) => damagePayout(insuredItems, damage)),
  );
  const cap = policyCap(insuredItems);

  return appendResult(state, { payout, remainingCap: cap - payout });
};

const runStep: StepRunner = (customer, state, step, stepIndex) =>
  isQuote(step)
    ? runQuoteStep(customer, state, step, stepIndex)
    : runClaimStep(customer, state, step, stepIndex);

