const remainingCapFor = (state: ScenarioState, step: Step): number =>
  step.policy === undefined
    ? 0
    : (state.remainingCapByStep.get(step.policy) ?? 0);

const runClaimStep: StepRunner = (_customer, state, step) => {
  const damages = step.incident?.damages ?? [];
  const insuredItems = insuredItemsFor(state, step);
  const remainingCap = remainingCapFor(state, step);

  // The clamp is outside the per-damage sum: the whole claim is limited by
  // what is left of the policy's cap, not each damage individually.
  const desiredPayout = sumOf(
    damages.map((damage) => damagePayout(insuredItems, damage)),
  );
  const payout = Math.min(desiredPayout, remainingCap);

  return {
    ...appendResult(state, { payout, remainingCap: remainingCap - payout }),
    remainingCapByStep: new Map(state.remainingCapByStep).set(
      step.policy ?? -1,
      remainingCap - payout,
    ),
  };
};

