const countByType = (types: string[]): Map<string, number> => {
  const counts = new Map<string, number>();

  for (const type of types) {
    counts.set(type, (counts.get(type) ?? 0) + 1);
  }

  return counts;
};

// Each damage entry is a separate damaged item, so a policy insuring one sword
// cannot suffer two sword damages. Over-claiming rejects the whole claim rather
// than the offending entry — the MHPCO does not part-settle a suspect report.
const rejectOverClaiming = (insuredItems: Item[], damages: Damage[]): void => {
  const insuredCounts = countByType(insuredItems.map((item) => item.type));

  for (const [itemType, claimed] of countByType(
    damages.map((damage) => damage.itemType),
  )) {
    const insured = insuredCounts.get(itemType) ?? 0;

    if (claimed > insured) {
      throw new Error(
        `claim reports ${claimed} damaged "${itemType}" but the policy covers ${insured}`,
      );
    }
  }
};

