  const result = runScenario({
    customer: { yearsWithMHPCO: 3 },
    steps: [
      { op: "quote", items: [rune] },
      { op: "quote", items: [rune] },
    ],
  });

  expect(result).toEqual({
    results: [{ premium: 28 }, { premium: 24 }],
  });
});

